def transform(g):
    bs=find_boxes(g)
    # pattern box: the one with interior cells
    def interior(b):
        v,r,c,h,w=b
        return sum(1 for y in range(r,r+h) for x in range(c,c+w) if g[y][x]==v)-2*h-2*w+4
    pat=[b for b in bs if interior(b)>0]
    empty=[b for b in bs if interior(b)<=0]
    p=pat[0]; v,r,c,h,w=p
    sub=[[g[y][x] for x in range(c,c+w)] for y in range(r,r+h)]
    sub=[[v if x==v else 0 for x in row] for row in sub]
    out=[[0]*len(g[0]) for _ in g]
    for y in range(r,r+h):
        for x in range(c,c+w):
            if sub[y-r][x-c]: out[y][x]=sub[y-r][x-c]
    for b in empty:
        v2,r2,c2,h2,w2=b
        if (h2,w2)==(h,w):
            for y in range(r2,r2+h2):
                for x in range(c2,c2+w2):
                    if sub[y-r2][x-c2]: out[y][x]=v2
    return out
